using Rts.Sim.Core;
using Rts.Sim.Effects;
using Rts.Sim.Ground;
using Rts.Sim.Tunnels;

namespace Rts.Sim;

// M3 coordination (OWNER: M3-01). Wave-1 packages do NOT edit this file: each fills the stub methods in its own partial file.
//
// StepCore order (Simulation.cs):
//   ApplyInput -> RunMissions -> RunMovement -> RunTunnels -> RunEffects -> RunCombat -> RunEconomy -> RunProduction
//   -> RunGround -> RunAiBookkeeping -> RunTriggers -> RunCleanup (removal, defeat, vision)
// Why: tunnels run after movement so a unit that walked onto its entrance this tick is drawn in, and before combat so
// underground units are already untargetable; effects (auras, stealth, charge) run before combat reads them; ground
// (radiation damage, Blackout decay, hardening recompute) runs after production so a building placed this tick is in the
// enclosure, and before cleanup so radiation kills are removed in the same tick.
//
// Package files and the stubs they fill:
//   Simulation.Tunnels.cs     M3-02  RunTunnelTransit, ApplyEnterTunnel, OnEntranceRemoving
//   Simulation.Burrow.cs      M3-03  RunBurrowing, ApplyDeployInto, ApplyUpgrade
//   Simulation.Hardening.cs   M3-04  RunHardening (+ team-aware gate pathing in Pathing/, placement exemption)
//   Simulation.Ground.cs      M3-05  RunRadiation, RunBlackout, RunStealth, IsSeismicRevealed, IsStealthedNow, IsJammedFor
//   Simulation.Effects.cs     M3-06  RunAuras, OnDeathWeapon
//   Simulation.Transport.cs   M3-06  ApplyBoard, ApplyUnload, ApplyEngineer, OnTransportDying
//   Simulation.Upgrades.cs    M3-06  ApplyBuildUpgrade, ApplyCancelUpgrade, RunUpgradeResearch, CanResearch
//   Simulation.Superweapon.cs M3-13  ApplySpecial, RunSuperweaponCharge
public sealed partial class Simulation
{
    /// <summary>Tunnel network, actor layers, telegraphs — the "tunnels" part (M3).</summary>
    public TunnelState Tunnels => _tunnels;

    /// <summary>Per-cell radiation, hardening and Blackout — the "ground" part (M3).</summary>
    public GroundState Ground => _ground;

    /// <summary>Per-actor aura multipliers, stealth timers, superweapon charge — the "effects" part (M3).</summary>
    public EffectsState Effects => _effects;

    /// <summary>True if <paramref name="player"/> has researched upgrade <paramref name="upgradeIndex"/> (index in SimRules.Upgrades).</summary>
    public bool HasUpgrade(byte player, int upgradeIndex) => _players.HasUpgrade(player, upgradeIndex);

    /// <summary>Layer of a vehicle or infantry slot (Surface for buildings).</summary>
    public ActorLayer LayerOf(ActorKind kind, int i) => _tunnels.LayerOf(kind, i);

    /// <summary>True if the mobile actor is underground (in a tunnel, burrowed, surfacing or a passenger).</summary>
    public bool IsUnderground(ActorKind kind, int i) => ActorLayers.IsUnderground(_tunnels.LayerOf(kind, i));

    // ---- step phases (order documented above) -----------------------------------------------------

    private void RunTunnels()
    {
        RunTunnelTransit();   // M3-02: draw queues in, advance transit, surface at exits
        RunBurrowing();       // M3-03: dive, travel burrowed, telegraphs, surfacing, Bore break-through, building morphs
    }

    private void RunEffects()
    {
        RunAuras();               // M3-06: every 10 ticks recompute aura multipliers
        RunStealth();             // M3-05: stealth timers
        RunSuperweaponCharge();   // M3-13
    }

    private void RunGround()
    {
        RunHardening();   // M3-04: recompute enclosure when Ground.HardeningDirty
        RunRadiation();   // M3-05: decay + damage
        RunBlackout();    // M3-05: Blackout timers
    }

    // ---- command routing ---------------------------------------------------------------------------

    /// <summary>Enter (payload in Command.cs): own/allied vehicle = board; own entrance building = tunnel transit with that
    /// destination; other building = engineer. Checks the subject is an own live mobile actor first.</summary>
    private void ApplyEnter(Command c)
    {
        var subjectKind = (ActorKind)(c.Arg & 0xFF);
        var targetKind = (ActorKind)((c.Arg >> 8) & 0xFF);
        Core.ActorRef subject = new(subjectKind, c.Subject);
        if (StoreOf(subjectKind) is not { } store || !store.Slots.IsAlive(c.Subject) || store.Player[c.Subject.Index] != c.Player) return;
        if (TryApplyRaid(c, subject)) return;   // M6-05: Simulation.Raid.cs
        switch (targetKind)
        {
            case ActorKind.Vehicle when _units.Slots.IsAlive(c.Target):
                if (subjectKind == ActorKind.Vehicle && TryApplyDock(c)) break;   // M7-09
                if (IsFriendly(c.Player, _units.Player[c.Target.Index])) ApplyBoard(c, subject);
                break;
            case ActorKind.Building when _buildings.Slots.IsAlive(c.Target):
                byte owner = _buildings.Player[c.Target.Index];
                if (owner == c.Player && BuildingTypeAt(c.Target.Index).Entrance != Rules.TunnelSize.None) ApplyEnterTunnel(c, subject);
                else if (IsGarrisonable(c.Target.Index) && CanGarrisonIn(c.Player, c.Target.Index)) ApplyGarrison(c, subject);   // M4-03
                else ApplyEngineer(c, subject);
                break;
        }
    }

    /// <summary>M4 routing rule (design 08 §3): a garrisonable building may be entered when it is own, allied, or neutral and
    /// empty. Anything else (an enemy building, an occupied neutral) falls through to the engineer action.</summary>
    private bool CanGarrisonIn(byte player, int b)
    {
        byte owner = _buildings.Player[b];
        if (IsFriendly(player, owner)) return true;
        return _players.IsNeutral(owner) && OccupantsIn(_buildings.Slots.IdOf(b)) == 0;
    }

    /// <summary>Deploy (payload in Command.cs): a transport unloads; a vehicle with DeploysInto deploys. Subject = own vehicle.</summary>
    private void ApplyDeploy(Command c)
    {
        if (!_units.Slots.IsAlive(c.Subject) || _units.Player[c.Subject.Index] != c.Player) return;
        Rules.VehicleType vt = RulesOf(c.Player).Vehicles[_units.TypeIndex[c.Subject.Index]];
        if (vt.Submerges) { ApplySubmerge(c); return; }   // M7-05
        if (vt.Passengers > 0 || vt.VehicleSlots > 0) ApplyUnload(c);   // M7-04b: vehicle_slots
        else if (vt.DeploysInto >= 0) ApplyDeployInto(c);
    }

    // ---- actor lifecycle hooks (called from Simulation.cs) ------------------------------------------

    /// <summary>A vehicle/infantry was just added to its store: reset the slot's M3 data (slots are reused).</summary>
    private void OnM3MobileSpawned(ActorKind kind, int i)
    {
        _tunnels.ClearMobile(kind, i);
        _effects.ClearMobile(kind, i);
        if (kind == ActorKind.Vehicle) _rigs.ClearVehicle(i);   // M6-02
        _veterancy.ClearMobile(kind, i);                        // VET-1
        if (kind == ActorKind.Vehicle) { _naval.ClearVehicle(i); _naval.AmmoLeft[i] = RulesOf(_units.Player[i]).Vehicles[_units.TypeIndex[i]].Ammo; }   // M7-02, D-156: starts full
        SupplyChanged();                                        // SUP-1
    }

    /// <summary>A vehicle/infantry with health &lt;= 0 is about to be removed (RunCleanup): death weapon, passengers.</summary>
    private void OnM3MobileDying(ActorKind kind, int i)
    {
        OnDeathWeapon(kind, i);                               // M3-06
        if (kind == ActorKind.Vehicle && IsCarrierType(RulesOf(_units.Player[i]).Vehicles[_units.TypeIndex[i]])) OnCarrierDying(i);   // M7-09
        if (kind == ActorKind.Vehicle) OnTransportDying(i);   // M3-06: passengers are lost
    }

    /// <summary>A vehicle/infantry slot is being freed: reset its M3 data.</summary>
    private void OnM3MobileRemoving(ActorKind kind, int i)
    {
        _tunnels.ClearMobile(kind, i);
        _effects.ClearMobile(kind, i);
        if (kind == ActorKind.Vehicle) _rigs.ClearVehicle(i);   // M6-02
        _veterancy.ClearMobile(kind, i);                        // VET-1
        if (kind == ActorKind.Vehicle) _naval.ClearVehicle(i);   // M7-02
        SupplyChanged();                                        // SUP-1
    }

    /// <summary>A building was just placed (setup, Place command or deploy).</summary>
    private void OnM3BuildingPlaced(int i)
    {
        _tunnels.ClearBuilding(i);
        _effects.ClearBuilding(i);
        _garrison.ClearBuilding(i);   // M4-01
        _rigs.ClearBuilding(i);       // M6-02
        SupplyChanged();              // SUP-1
        if (IsSealPiece(i)) _ground.HardeningDirty = true;
        BeachheadOnPlaced(i);         // M7-07
    }

    /// <summary>A building is being removed (destroyed or sold): exit-lost handling, hardening, slot reset.</summary>
    private void OnM3BuildingRemoving(int i)
    {
        if (BuildingTypeAt(i).Entrance != Rules.TunnelSize.None) OnEntranceRemoving(i);   // M3-02: D2 re-route
        if (IsGarrisonable(i)) OnGarrisonBuildingRemoving(i);   // M4-03: eject occupants (cells still held)
        if (IsSealPiece(i)) _ground.HardeningDirty = true;
        BeachheadOnRemoving(i);       // M7-07
        _tunnels.ClearBuilding(i);
        _effects.ClearBuilding(i);
        _garrison.ClearBuilding(i);   // M4-01
        _rigs.ClearBuilding(i);       // M6-02
        SupplyChanged();              // SUP-1
    }

    /// <summary>Walls, gates and structures all count for the enclosure (design 05 §2); every building is a seal piece today.</summary>
    private bool IsSealPiece(int i) => _buildings.Slots.IsIndexAlive(i);

    // ---- fog for M3 layers (views use these; packages fill the predicates) --------------------------

    /// <summary>
    /// True if a live vehicle/infantry must be hidden from <paramref name="viewer"/> even when its cell is in vision: it is
    /// underground and not revealed by the viewer team's Seismograph, or stealthed and not revealed. Friendly actors are never
    /// hidden.
    /// </summary>
    internal bool IsHiddenFrom(byte viewer, ActorKind kind, int i)
    {
        byte owner = PlayerAt(kind, i);
        if (IsFriendly(viewer, owner)) return false;
        ActorLayer layer = _tunnels.LayerOf(kind, i);
        CellCoord cell = PositionAt(kind, i).ToCell();
        if (layer is ActorLayer.Tunnel or ActorLayer.Passenger or ActorLayer.Garrisoned) return true;   // inside a network, a transport or a garrison (M4): never seen
        if (layer is ActorLayer.Burrowed or ActorLayer.Surfacing) return !IsSeismicRevealed(viewer, cell);
        if (IsSubmergedShip(kind, i)) return !IsSonarRevealed(viewer, cell);   // M7-05
        return IsStealthedNow(kind, i) && !IsStealthRevealed(viewer, cell);
    }
}
